// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ProductRegistry
 * @dev Хранит реестр товаров для децентрализованного маркетплейса Amanita.
 * - Хранит только ссылку (ipfsCID) на JSON-метаданные товара.
 * - Не хранит фото и большие данные on-chain (экономия газа).
 * - Продавцы могут создавать, обновлять, деактивировать свои товары.
 * - Другие пользователи могут читать товары.
 * - Все запросы читаемые (view), минимальный газ.
 */
interface ISpiralEngine {
    function usedInviteByUser(address user) external view returns (uint256);
    function hasRole(bytes32 role, address account) external view returns (bool);
}

// Роль продавца в SpiralEngine
bytes32 constant SELLER_ROLE = keccak256("SELLER_ROLE");

contract ProductRegistry {
    /// @notice Структура товара
    struct Product {
        uint256 id;          // Уникальный идентификатор товара
        address seller;      // Продавец (автор записи)
        string ipfsCID;      // Ссылка на JSON-описание (IPFS CID)
        bool active;         // Активен ли товар
    }

    /// @notice SpiralEngine для проверки активации пользователя
    ISpiralEngine public spiralEngine;

    /// @notice Конструктор
    /// @param _spiralEngine адрес контракта SpiralEngine
    constructor(address _spiralEngine) {
        require(_spiralEngine != address(0), "Invalid SpiralEngine address");
        spiralEngine = ISpiralEngine(_spiralEngine);
    }

    // Версия каталога продавца
    mapping(address => uint256) public catalogVersion;

    /// @notice Маппинг: productId => Product
    mapping(uint256 => Product) private products;

    /// @notice Счётчик всех товаров (для генерации id)
    uint256 private _productIdCounter;

    /// @notice Маппинг: продавец => список всех productId
    /// Это помогает быстро получить товары продавца (экономия off-chain фильтра)
    mapping(address => uint256[]) private productsBySeller;

    /// @notice Список всех активных товаров (id)
    /// Можно вернуть список всех id для фронтенда — дешевле, чем Product[]
    uint256[] private activeProductIds;

    // --------------------------------
    // ------- События ---------------
    // --------------------------------

    /// @notice Событие: создан новый товар
    event ProductCreated(address indexed seller,
        uint256 productId,
        string ipfsCID,
        uint256 status);

    /// @notice Событие: обновлён товар
    event ProductUpdated(
        address indexed seller,
        uint256 productId,
        string ipfsCID,
        uint256 price,
        uint256 status
    );

    /// @notice Событие: товар деактивирован
    event ProductDeactivated(uint256 indexed productId);

    /// @notice Событие: обновлена версия каталога продавца
    event CatalogUpdated(address indexed seller, uint256 newVersion);

    /// @notice Событие: каталог продавца полностью очищен
    event CatalogCleared(address indexed seller, uint256 productsCleared);

    // --------------------------------
    // ------- Модификаторы ----------
    // --------------------------------

    /**
     * @dev Проверка, что msg.sender — активированный пользователь (SpiralEngine).
     */
    modifier onlyActivatedUser() {
        require(spiralEngine.usedInviteByUser(msg.sender) > 0, "Not activated in SpiralEngine");
        _;
    }

    /**
     * @dev Проверка, что msg.sender — продавец указанного товара.
     * @param productId id товара
     */
    modifier onlyOwnSellerProduct(uint256 productId) {
        require(products[productId].seller == msg.sender, "Not product seller");
        _;
    }

    // --------------------------------
    // ------- Основные методы -------
    // --------------------------------

    /**
    * @notice Создать новый товар.
    * @dev
     * - Проверяет, что пользователь активирован (SpiralEngine).
    * - Проверяет, что CID не пустой и цена > 0.
    * - Генерирует уникальный productId.
    * - Сохраняет товар в маппинг продуктов.
    * - Добавляет productId в общий список активных товаров и в индекс продавца.
    * - Эмиттирует событие ProductCreated для трекинга.
    *
    * Критерии приёмки:
    * - Пользователь активирован.
    * - CID не пустой.
    * - Цена > 0.
    * - Все индексы обновлены (activeProductIds, productsBySeller).
    * - Данные доступны через getProduct, getAllActiveProductIds и getProductsBySeller.
    * - Событие ProductCreated доступно для фронтенда.
    *
    * Эффективность газа:
    * - O(1) операции без циклов.
    * - Минимальные storage-записи (только 3 массива и 1 mapping).
    */
    function createProduct(string calldata ipfsCID) external {
        require(bytes(ipfsCID).length > 0, "ProductRegistry: empty CID");

        // Генерируем новый productId
        _productIdCounter += 1;
        uint256 newProductId = _productIdCounter;

        // Создаём продукт в памяти (неактивный по умолчанию)
        Product memory newProduct = Product({
            id: newProductId,
            seller: msg.sender,
            ipfsCID: ipfsCID,
            active: false
        });

        // Сохраняем в storage
        products[newProductId] = newProduct;

        // НЕ добавляем в список активных товаров (продукт создается неактивным)

        // Добавляем productId в индекс продавца
        productsBySeller[msg.sender].push(newProductId);

        // Эмитим событие для фронтенда (статус 0 - неактивный)
        emit ProductCreated(msg.sender, newProductId, ipfsCID, 0);

        catalogVersion[msg.sender] += 1;
        emit CatalogUpdated(msg.sender, catalogVersion[msg.sender]);
    }


    /**
    * @notice Обновить товар (ipfsCID или цену).
    * @dev
    * - Продавец может обновлять только свой товар.
    * - CID и цена должны быть валидными (не пустой и > 0).
    * - Обновления сохраняются в storage.
    * - Эмиттируется событие ProductUpdated.
    *
    * Acceptance criteria:
    * - Продавец = msg.sender (onlySeller)
    * - CID != пустой, цена > 0
    * - Товар активен (не обновляем архивные)
    * - Поля ipfsCID и price обновлены
    * - Эмиттирован ProductUpdated
    *
    * Gas-эффективность:
    * - Прямой доступ к storage (O(1))
    * - Нет циклов или лишних вычислений
    */
    function updateProduct(uint256 productId, string calldata newIpfsCID, uint256 newPrice) external onlyOwnSellerProduct(productId) {
        require(bytes(newIpfsCID).length > 0, "ProductRegistry: empty CID");
        require(newPrice > 0, "ProductRegistry: price must be > 0");

        Product storage product = products[productId];
        require(product.active, "ProductRegistry: product not active");

        product.ipfsCID = newIpfsCID;

        emit ProductUpdated(msg.sender, productId, newIpfsCID, newPrice, 1);

        catalogVersion[msg.sender] += 1;  // обновляем только для этого продавца
        emit CatalogUpdated(msg.sender, catalogVersion[msg.sender]);
    }

    /**
    * @notice Деактивировать товар (сделать его невидимым в каталоге).
    * @dev
    * - Продавец может деактивировать только свой товар.
    * - Товар должен быть активным.
    * - Статус `active = false`.
    * - Удаляет productId из списка активных товаров через swap-and-pop (газ-эффективно).
    * - Эмиттирует событие ProductDeactivated.
    *
    * Acceptance criteria:
    * - Проверка продавца (onlySeller)
    * - Проверка, что товар активен
    * - Обновлён статус в storage
    * - Удалён из массива активных
    * - Эмиттировано событие
    *
    * Газ-эффективность:
    * - O(n) поиск + O(1) удаление (swap-and-pop)
    * - Никаких лишних storage-переменных
    */
    function deactivateProduct(uint256 productId) external onlyOwnSellerProduct(productId) {
        Product storage product = products[productId];
        require(product.active, "ProductRegistry: already deactivated");

        product.active = false;

        // Удаляем productId из списка активных товаров (экономия газа через swap-and-pop)
        uint256 len = activeProductIds.length;
        for (uint256 i = 0; i < len; i++) {
            if (activeProductIds[i] == productId) {
                // Меняем местами с последним элементом и убираем
                activeProductIds[i] = activeProductIds[len - 1];
                activeProductIds.pop();
                break;
            }
        }

        emit ProductDeactivated(productId);

        catalogVersion[msg.sender] += 1;  // обновляем только для этого продавца
        emit CatalogUpdated(msg.sender, catalogVersion[msg.sender]);
    }

    /**
    * @notice Активировать товар (сделать его видимым в каталоге).
    * @dev
    * - Продавец может активировать только свой товар.
    * - Товар должен быть неактивным.
    * - Статус `active = true`.
    * - Добавляет productId в список активных товаров.
    * - Эмиттирует событие ProductUpdated.
    *
    * Acceptance criteria:
    * - Проверка продавца (onlyOwnSellerProduct)
    * - Проверка, что товар неактивен
    * - Обновлён статус в storage
    * - Добавлен в массив активных
    * - Эмиттировано событие
    *
    * Газ-эффективность:
    * - O(1) операции без циклов
    * - Минимальные storage-операции
    */
    function activateProduct(uint256 productId) external onlyOwnSellerProduct(productId) {
        Product storage product = products[productId];
        require(!product.active, "ProductRegistry: already active");

        product.active = true;

        // Добавляем productId в список активных товаров
        activeProductIds.push(productId);

        emit ProductUpdated(msg.sender, productId, product.ipfsCID, 0, 1);

        catalogVersion[msg.sender] += 1;  // обновляем только для этого продавца
        emit CatalogUpdated(msg.sender, catalogVersion[msg.sender]);
    }

    // --------------------------------
    // ------- View функции ----------
    // --------------------------------

    /**
    * @notice Получить данные товара.
    * @dev
    * - Доступна любому (public view).
    * - Проверяет существование (product.id != 0).
    * - Возвращает полные данные: id, seller, ipfsCID, price, active.
    *
    * Acceptance criteria:
    * - Возвращает существующую структуру Product.
    * - Реверт, если товар не существует.
    *
    * Газ-эффективность:
    * - Только чтение (view).
    * - Никаких циклов или лишних storage-запросов.
    */
    function getProduct(uint256 productId) external view returns (Product memory) {
        Product memory product = products[productId];
        require(product.id != 0, "ProductRegistry: product does not exist");
        return product;
    }

    /**
    * @notice Получить список id всех активных товаров.
    * @dev
    * - Публичная view-функция.
    * - Отдаёт snapshot массива activeProductIds.
    * - Экономично по газу (только чтение, нет циклов).
    *
    * Acceptance criteria:
    * - Отдаёт все id активных товаров (актуально в момент запроса).
    * - Прозрачность — любой может получить каталог.
    *
    * Газ-эффективность:
    * - O(1) чтение ссылки на storage-массив (view → memory).
    * - Нет вычислений/фильтрации.
    */
    function getAllActiveProductIds() external view returns (uint256[] memory) {
        return activeProductIds;
    }

    /**
    * @notice Получить список id всех товаров продавца.
    * @dev
    * - Public view.
    * - Не фильтрует по active — возвращает все товары (для прозрачности и истории).
    * - Лёгкое, дешёвое по газу (view → memory).
    *
    * Acceptance criteria:
    * - Возвращает массив id всех товаров продавца.
    * - Прозрачность — любой может получить историю продаж.
    *
    * Газ-эффективность:
    * - O(1) чтение ссылки на storage-массив.
    * - Никаких вычислений внутри функции.
    */
    function getProductsBySeller(address seller) external view returns (uint256[] memory) {
        return productsBySeller[seller];
    }

    /**
    * @notice Получить версию каталога продавца.
    * @dev
    * - Public view.
    * - Возвращает текущую версию каталога номер которой увеличивается при каждом 
    * обновлении или добавлении любого товара.
    *
    */
    function getMyCatalogVersion() external view returns (uint256) {
        require(spiralEngine.hasRole(SELLER_ROLE, msg.sender), "Not a seller");
        return catalogVersion[msg.sender];
    }

    /**
    * @notice Получить все товары продавца вместе со структурой Product.
    * @dev
    * - Public view.
    * - Возвращает все товары продавца.
    *
    */
    /**
    * @notice Получить все товары продавца вместе со структурой Product.
    * @dev
    * - Public view.
    * - Возвращает все товары продавца.
    */
    function getProductsBySellerFull() external view returns (Product[] memory) {
        require(spiralEngine.hasRole(SELLER_ROLE, msg.sender), "Not a seller");

        uint256[] memory sellerProductIds = productsBySeller[msg.sender];
        Product[] memory sellerProducts = new Product[](sellerProductIds.length);
        for (uint256 i = 0; i < sellerProductIds.length; i++) {
            sellerProducts[i] = products[sellerProductIds[i]];
        }
        return sellerProducts;
    }

    // --------------------------------
    // ------- Вспомогательные функции -
    // --------------------------------

    /**
    * @notice Удалить продукт из списка активных продуктов (внутренняя функция).
    * @dev
    * - Использует swap-and-pop алгоритм для эффективного удаления.
    * - O(n) поиск + O(1) удаление.
    * - Приватная функция для внутреннего использования.
    * @param productId ID продукта для удаления
    */
    function _removeFromActiveProducts(uint256 productId) private {
        uint256 len = activeProductIds.length;
        for (uint256 i = 0; i < len; i++) {
            if (activeProductIds[i] == productId) {
                // Swap-and-pop: меняем местами с последним элементом и удаляем
                activeProductIds[i] = activeProductIds[len - 1];
                activeProductIds.pop();
                break;
            }
        }
    }

    /**
    * @notice Проверить, существует ли каталог у продавца (внутренняя функция).
    * @dev
    * - Проверяет наличие продуктов в индексе продавца.
    * - Возвращает true, если каталог не пуст.
    * - Используется для валидации перед операциями очистки.
    * @param seller Адрес продавца для проверки
    * @return bool True, если каталог существует и не пуст
    */
    function _hasCatalog(address seller) private view returns (bool) {
        return productsBySeller[seller].length > 0;
    }

    // --------------------------------
    // ------- Методы очистки ---------
    // --------------------------------

    /**
    * @notice Полностью очистить каталог продавца.
    * @dev
    * - Удаляет все продукты продавца из всех индексов.
    * - Очищает activeProductIds для активных продуктов.
    * - Удаляет все записи из products mapping.
    * - Очищает productsBySeller индекс.
    * - Обновляет версию каталога.
    * - Эмитирует события для отслеживания.
    * 
    * Требования безопасности:
    * - Только продавец может очистить свой каталог.
     * - Продавец должен быть активирован в SpiralEngine.
    * 
    * Газ-эффективность:
    * - O(n) для удаления из activeProductIds.
    * - O(1) для очистки индексов.
    * - Минимальные storage операции.
    * 
    * @param seller Адрес продавца, каталог которого нужно очистить
    */
    function clearSellerCatalog(address seller) external {
        // 1. Проверка доступа - только продавец может очистить свой каталог
        require(spiralEngine.hasRole(SELLER_ROLE, msg.sender), "Not a seller");
        require(seller == msg.sender, "Can only clear own catalog");
        require(seller != address(0), "Invalid seller address");

        // 2. Проверка существования каталога
        require(_hasCatalog(seller), "Catalog is already empty");

        // 3. Получение списка продуктов продавца
        uint256[] memory sellerProducts = productsBySeller[seller];
        uint256 productCount = sellerProducts.length;

        // 4. Очистка активных продуктов из общего списка
        // Защита от переполнения: проверяем разумный лимит продуктов
        require(productCount <= 10000, "Catalog too large for single operation");

        for (uint256 i = 0; i < productCount; i++) {
            uint256 productId = sellerProducts[i];
            Product storage product = products[productId];

            // Дополнительная проверка существования продукта
            require(product.id != 0, "Product does not exist");
            require(product.seller == seller, "Product ownership mismatch");

            // Удаляем из списка активных, если продукт активен
            if (product.active) {
                _removeFromActiveProducts(productId);
            }

            // Удаляем продукт из основного хранилища
            delete products[productId];
        }

        // 5. Очистка индекса продавца
        delete productsBySeller[seller];

        // 6. Обновление версии каталога
        catalogVersion[seller] += 1;

        // 7. Эмиссия событий
        emit CatalogCleared(seller, productCount);
        emit CatalogUpdated(seller, catalogVersion[seller]);
    }

}

contracts/SoulboundCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/IERC721Metadata.sol";
import "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./IERC5192.sol";

/**
 * @dev Интерфейс для контракта метаданных
 */
interface ISoulMetadata {
    function getTokenURI(uint256 tokenId) external view returns (string memory);
}

/**
 * @dev Интерфейс для контракта восстановления
 */
interface ISoulRecovery {
    function canConfirmRecovery(uint256 tokenId) external view returns (bool);
}

/**
 * @dev Интерфейс для контракта интеграции
 */
interface ISoulIntegration {
    function notifySoulCreated(uint256 tokenId, address owner) external;
    function notifySoulRecovered(uint256 tokenId, address oldOwner, address newOwner) external;
}

/**
 * @title SoulboundCore
 * @author Zeya888 (https://zeya888.me)
 * @dev Минимальная, газоэффективная реализация Soulbound Token согласно EIP-5192
 * @notice Всегда заблокированные токены - нет дополнительных проверок для экономии газа
 */
contract SoulboundCore is IERC165, IERC721, IERC721Metadata, IERC5192, Ownable {

    // === СОБЫТИЯ ===

    /**
     * @dev Событие при минтинге SBT токена
     * @param to получатель токена
     * @param tokenId идентификатор токена
     */
    event SoulMinted(address indexed to, uint256 indexed tokenId);

    /**
     * @dev Событие при сжигании SBT токена
     * @param tokenId идентификатор токена
     */
    event SoulBurned(uint256 indexed tokenId);

    // === ХРАНИЛИЩЕ ===

    string private _name;
    string private _symbol;
    uint256 private _nextTokenId = 1;
    uint256 private _totalSupply = 0;

    // Mapping от tokenId к владельцу
    mapping(uint256 => address) private _owners;

    // Mapping от адреса к количеству токенов
    mapping(address => uint256) private _balances;

    // Адрес контракта метаданных (опционально)
    address private _metadataContract;

    // Адрес контракта восстановления (опционально)
    address private _recoveryContract;

    // Адрес контракта интеграции (опционально)
    address private _integrationContract;

    // === КОНСТРУКТОР ===

    constructor(string memory name_, string memory symbol_) Ownable(msg.sender) {
        _name = name_;
        _symbol = symbol_;
    }

    // === ERC721 VIEW FUNCTIONS ===

    function name() public view override returns (string memory) {
        return _name;
    }

    function symbol() public view override returns (string memory) {
        return _symbol;
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        require(_owners[tokenId] != address(0), "ERC721: invalid token ID");

        // Если контракт метаданных установлен, используем его
        if (_metadataContract != address(0)) {
            try ISoulMetadata(_metadataContract).getTokenURI(tokenId) returns (string memory uri) {
                // Если метаданные пустые, используем базовые
                if (bytes(uri).length > 0) {
                    return uri;
                }
                return _getDefaultTokenURI(tokenId);
            } catch {
                // Fallback к базовым метаданным при ошибке
                return _getDefaultTokenURI(tokenId);
            }
        }

        // Базовые метаданные без внешнего контракта
        return _getDefaultTokenURI(tokenId);
    }

    function balanceOf(address owner) public view override returns (uint256) {
        require(owner != address(0), "ERC721: address zero is not a valid owner");
        return _balances[owner];
    }

    function ownerOf(uint256 tokenId) public view override returns (address) {
        return _requireOwned(tokenId);
    }

    function supportsInterface(bytes4 interfaceId) public view override returns (bool) {
        return interfaceId == type(IERC165).interfaceId ||
               interfaceId == type(IERC721).interfaceId ||
               interfaceId == type(IERC721Metadata).interfaceId ||
               interfaceId == type(IERC5192).interfaceId;
    }

    // === SBT CORE FUNCTIONS ===

    /**
     * @dev SBT токены заблокированы навсегда - всегда возвращает true
     * @return true всегда
     */
    function locked(uint256 /* tokenId */) external pure override returns (bool) {
        return true;
    }

    /**
     * @dev SBT токены не могут быть одобрены - всегда revert
     */
    function approve(address /* to */, uint256 /* tokenId */) public pure override {
        revert("SBT: approval not allowed");
    }

    /**
     * @dev SBT токены не могут быть одобрены глобально - всегда revert
     */
    function setApprovalForAll(address /* operator */, bool /* approved */) public pure override {
        revert("SBT: approval not allowed");
    }

    /**
     * @dev SBT токены не имеют одобренных операторов - всегда возвращает address(0)
     * @return address(0) всегда
     */
    function getApproved(uint256 /* tokenId */) public pure override returns (address) {
        return address(0);
    }

    /**
     * @dev SBT токены не имеют глобальных одобрений - всегда возвращает false
     * @return false всегда
     */
    function isApprovedForAll(address /* owner */, address /* operator */) public pure override returns (bool) {
        return false;
    }

    // === TRANSFER FUNCTIONS ===

    /**
     * @dev SBT токены не могут быть переданы - всегда revert
     */
    function transferFrom(address /* from */, address /* to */, uint256 /* tokenId */) public pure override {
        revert("SBT: transfer not allowed");
    }

    /**
     * @dev SBT токены не могут быть безопасно переданы - всегда revert
     */
    function safeTransferFrom(address /* from */, address /* to */, uint256 /* tokenId */) public pure override {
        revert("SBT: transfer not allowed");
    }

    /**
     * @dev SBT токены не могут быть безопасно переданы с данными - всегда revert
     */
    function safeTransferFrom(address /* from */, address /* to */, uint256 /* tokenId */, bytes memory /* data */) public pure override {
        revert("SBT: transfer not allowed");
    }

    // === MINTING FUNCTIONS ===

    /**
     * @dev Минтинг SBT токена (только владелец контракта)
     * @param to получатель токена
     * @return tokenId идентификатор созданного токена
     */
    function mintSoul(address to) external onlyOwner returns (uint256) {
        uint256 tokenId = _nextTokenId++;

        _safeMint(to, tokenId);

        emit SoulMinted(to, tokenId);
        emit Locked(tokenId);

        // Уведомление интеграционного контракта (опционально)
        _notifyIntegration(tokenId, to, "created");

        return tokenId;
    }

    /**
     * @dev Массовый минтинг SBT токенов (только владелец контракта)
     * @param to получатель токенов
     * @param amount количество токенов для минтинга
     * @return tokenIds массив идентификаторов созданных токенов
     */
    function mintSoulBatch(address to, uint256 amount) external onlyOwner returns (uint256[] memory) {
        require(amount > 0 && amount <= 100, "SBT: invalid amount");

        uint256[] memory tokenIds = new uint256[](amount);

        for (uint256 i = 0; i < amount; i++) {
            uint256 tokenId = _nextTokenId++;

            _safeMint(to, tokenId);

            emit SoulMinted(to, tokenId);
            emit Locked(tokenId);

            // Уведомление интеграционного контракта (опционально)
            _notifyIntegration(tokenId, to, "created");

            tokenIds[i] = tokenId;
        }

        return tokenIds;
    }

    // === BURNING FUNCTIONS ===

    /**
     * @dev Сжигание SBT токена (только владелец токена или владелец контракта)
     * @param tokenId идентификатор токена для сжигания
     */
    function burnSoul(uint256 tokenId) external {
        require(
            _isAuthorized(ownerOf(tokenId), msg.sender, tokenId) || msg.sender == owner(),
            "SBT: not authorized to burn"
        );

        _burn(tokenId);

        emit SoulBurned(tokenId);
    }

    // === VIEW FUNCTIONS ===

    /**
     * @dev Получить следующий доступный tokenId
     * @return следующий tokenId
     */
    function getNextTokenId() external view returns (uint256) {
        return _nextTokenId;
    }

    /**
     * @dev Получить общее количество заминченных токенов
     * @return количество токенов
     */
    function getTotalSupply() external view returns (uint256) {
        return _totalSupply;
    }

    /**
     * @dev Проверить, существует ли токен
     * @param tokenId идентификатор токена
     * @return true если токен существует
     */
    function exists(uint256 tokenId) external view returns (bool) {
        return _owners[tokenId] != address(0);
    }

    // === METADATA MANAGEMENT ===

    /**
     * @dev Установить адрес контракта метаданных (только владелец)
     * @param metadataContract адрес контракта метаданных
     */
    function setMetadataContract(address metadataContract) external onlyOwner {
        _metadataContract = metadataContract;
    }

    /**
     * @dev Получить адрес контракта метаданных
     * @return адрес контракта метаданных
     */
    function getMetadataContract() external view returns (address) {
        return _metadataContract;
    }

    /**
     * @dev Установить адрес контракта восстановления (только владелец)
     * @param recoveryContract адрес контракта восстановления
     */
    function setRecoveryContract(address recoveryContract) external onlyOwner {
        _recoveryContract = recoveryContract;
    }

    /**
     * @dev Получить адрес контракта восстановления
     * @return адрес контракта восстановления
     */
    function getRecoveryContract() external view returns (address) {
        return _recoveryContract;
    }

    /**
     * @dev Установить адрес контракта интеграции (только владелец)
     * @param integrationContract адрес контракта интеграции
     */
    function setIntegrationContract(address integrationContract) external onlyOwner {
        _integrationContract = integrationContract;
    }

    /**
     * @dev Получить адрес контракта интеграции
     * @return адрес контракта интеграции
     */
    function getIntegrationContract() external view returns (address) {
        return _integrationContract;
    }

    /**
     * @dev Выполнить восстановление токена (только recovery контракт)
     * @param tokenId идентификатор токена
     * @param newOwner новый владелец
     */
    function executeRecovery(uint256 tokenId, address newOwner) external {
        require(msg.sender == _recoveryContract, "SoulboundCore: not recovery contract");
        require(_recoveryContract != address(0), "SoulboundCore: no recovery contract");
        require(_owners[tokenId] != address(0), "ERC721: invalid token ID");
        require(newOwner != address(0), "SoulboundCore: invalid new owner");

        // Проверяем, что recovery контракт подтверждает возможность восстановления
        require(
            ISoulRecovery(_recoveryContract).canConfirmRecovery(tokenId),
            "SoulboundCore: recovery not confirmed"
        );

        address oldOwner = _owners[tokenId];

        // Обновляем владение
        _balances[oldOwner] -= 1;
        _balances[newOwner] += 1;
        _owners[tokenId] = newOwner;

        emit Transfer(oldOwner, newOwner, tokenId);

        // Уведомление интеграционного контракта о восстановлении (опционально)
        _notifyIntegrationRecovery(tokenId, oldOwner, newOwner);
    }

    // === INTERNAL FUNCTIONS ===

    function _requireOwned(uint256 tokenId) internal view returns (address) {
        address owner = _owners[tokenId];
        require(owner != address(0), "ERC721: invalid token ID");
        return owner;
    }

    function _safeMint(address to, uint256 tokenId) internal {
        _mint(to, tokenId);
        require(_checkOnERC721Received(address(0), to, tokenId, ""), "ERC721: transfer to non ERC721Receiver implementer");
    }

    function _mint(address to, uint256 tokenId) internal {
        require(to != address(0), "ERC721: mint to the zero address");
        require(_owners[tokenId] == address(0), "ERC721: token already minted");

        _balances[to] += 1;
        _owners[tokenId] = to;
        _totalSupply += 1;

        emit Transfer(address(0), to, tokenId);
    }

    function _burn(uint256 tokenId) internal {
        address owner = ownerOf(tokenId);

        _balances[owner] -= 1;
        delete _owners[tokenId];
        _totalSupply -= 1;

        emit Transfer(owner, address(0), tokenId);
    }

    function _isAuthorized(address owner, address spender, uint256 tokenId) internal view returns (bool) {
        return (spender == owner || isApprovedForAll(owner, spender) || getApproved(tokenId) == spender);
    }

    /**
     * @dev Генерация базовых метаданных для токена
     * @param tokenId идентификатор токена
     * @return JSON строка с базовыми метаданными
     */
    function _getDefaultTokenURI(uint256 tokenId) internal view returns (string memory) {
        return string(abi.encodePacked(
            '{"name": "Soul #', _toString(tokenId), 
            '", "description": "Soulbound Token from Amanita Ecosystem",',
            '"type": "basic",',
            '"version": 1,',
            '"attributes": []',
            '}'
        ));
    }

    /**
     * @dev Преобразование uint256 в string
     * @param value число для преобразования
     * @return строковое представление числа
     */
    function _toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) {
            return "0";
        }
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }

    function _checkOnERC721Received(address from, address to, uint256 tokenId, bytes memory data) internal returns (bool) {
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 retval) {
                return retval == IERC721Receiver.onERC721Received.selector;
            } catch (bytes memory reason) {
                if (reason.length == 0) {
                    revert("ERC721: transfer to non ERC721Receiver implementer");
                } else {
                    assembly {
                        revert(add(32, reason), mload(reason))
                    }
                }
            }
        } else {
            return true;
        }
    }

    /**
     * @dev Внутренняя функция для уведомления интеграционного контракта
     * @param tokenId идентификатор токена
     * @param owner владелец токена
     */
    function _notifyIntegration(uint256 tokenId, address owner, string memory /* eventType */) internal {
        if (_integrationContract != address(0)) {
            try ISoulIntegration(_integrationContract).notifySoulCreated(tokenId, owner) {
                // Успешное уведомление, ничего не делаем
            } catch {
                // Graceful degradation - игнорируем ошибки интеграции
            }
        }
    }

    /**
     * @dev Внутренняя функция для уведомления о восстановлении
     * @param tokenId идентификатор токена
     * @param oldOwner предыдущий владелец
     * @param newOwner новый владелец
     */
    function _notifyIntegrationRecovery(uint256 tokenId, address oldOwner, address newOwner) internal {
        if (_integrationContract != address(0)) {
            try ISoulIntegration(_integrationContract).notifySoulRecovered(tokenId, oldOwner, newOwner) {
                // Успешное уведомление, ничего не делаем
            } catch {
                // Graceful degradation - игнорируем ошибки интеграции
            }
        }
    }
}

contracts/SoulIdentity.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "./interfaces/ISoulIdentity.sol";

/**
 * @dev Интерфейс для SoulboundCore - существующий SBT контракт
 */
interface ISoulboundCore {
    function balanceOf(address owner) external view returns (uint256);
    function ownerOf(uint256 tokenId) external view returns (address);
    function mintSoul(address to) external;
    function exists(uint256 tokenId) external view returns (bool);
    function getTotalSupply() external view returns (uint256);
    function getNextTokenId() external view returns (uint256);
}

/**
 * @dev Интерфейс для SoulMetadata - существующая система метаданных
 */
interface ISoulMetadata {
    struct SoulData {
        string metadataType;
        uint256 version;
        string attributes;
        string ipfsHash;
    }

    function getMetadata(uint256 tokenId) external view returns (SoulData memory);
    function initializeMetadata(uint256 tokenId, string memory metadataType, string memory attributes, string memory ipfsHash) external;
    function updateMetadata(uint256 tokenId, string memory attributes, string memory ipfsHash) external;
    function isInitialized(uint256 tokenId) external view returns (bool);
}

/**
 * @title SoulIdentity
 * @author Zeya888 (https://zeya888.me)
 * @dev МОСТ-контракт между SpiralEngine и существующей SBT экосистемой
 * @notice НЕ создает новые SBT токены - использует существующие SoulboundCore!
 * @notice Добавляет только DID функциональность к существующим SBT
 */
contract SoulIdentity is AccessControl, ISoulIdentity {

    // === РОЛИ ===
    bytes32 public constant SPIRAL_ENGINE_ROLE = keccak256("SPIRAL_ENGINE_ROLE");

    // === ИНТЕГРАЦИЯ С СУЩЕСТВУЮЩИМИ КОНТРАКТАМИ ===
    ISoulboundCore public soulboundCore;
    ISoulMetadata public soulMetadata;

    // === НОВЫЕ DID ДАННЫЕ ===
    mapping(address => ExternalIdentity[]) private userIdentities;
    mapping(address => uint256) private primaryIdentityIndex;
    mapping(address => mapping(string => uint256)) private identityTypeToIndex;

    // === СОБЫТИЯ ===
    event SoulIdentityContractsUpdated(address soulboundCore, address soulMetadata);

    // === КОНСТРУКТОР ===

    /**
     * @dev Инициализация моста с существующими SBT контрактами
     * @param _soulboundCore адрес существующего SoulboundCore контракта
     * @param _soulMetadata адрес существующего SoulMetadata контракта
     */
    constructor(address _soulboundCore, address _soulMetadata) {
        require(_soulboundCore != address(0), "SoulIdentity: invalid soulbound core address");
        require(_soulMetadata != address(0), "SoulIdentity: invalid soul metadata address");

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(SPIRAL_ENGINE_ROLE, msg.sender);

        soulboundCore = ISoulboundCore(_soulboundCore);
        soulMetadata = ISoulMetadata(_soulMetadata);

        emit SoulIdentityContractsUpdated(_soulboundCore, _soulMetadata);
    }

    // === ДЕЛЕГИРОВАНИЕ К СУЩЕСТВУЮЩИМ SBT КОНТРАКТАМ ===

    /**
     * @dev Получить уровень души через делегирование к SoulMetadata
     * @param user адрес пользователя
     * @return уровень души (1 если нет данных)
     */
    function getSoulLevel(address user) external view override returns (uint256) {
        uint256 tokenId = _getUserTokenId(user);
        if (tokenId == 0) return 0; // Нет SBT токена

        try soulMetadata.getMetadata(tokenId) returns (ISoulMetadata.SoulData memory data) {
            return _parseLevel(data.attributes); // Парсим level из JSON
        } catch {
            return 1; // Дефолтный уровень
        }
    }

    /**
     * @dev Получить репутацию души через делегирование к SoulMetadata
     * @param user адрес пользователя
     * @return репутация души (100 если нет данных)
     */
    function getSoulReputation(address user) external view override returns (uint256) {
        uint256 tokenId = _getUserTokenId(user);
        if (tokenId == 0) return 0; // Нет SBT токена

        try soulMetadata.getMetadata(tokenId) returns (ISoulMetadata.SoulData memory data) {
            return _parseReputation(data.attributes); // Парсим reputation из JSON
        } catch {
            return 100; // Дефолтная репутация
        }
    }

    /**
     * @dev Обновить уровень души через SoulMetadata
     * @param user адрес пользователя
     * @param newLevel новый уровень души
     */
    function updateSoulLevel(address user, uint256 newLevel) external override onlyRole(SPIRAL_ENGINE_ROLE) {
        uint256 tokenId = _getUserTokenId(user);
        require(tokenId > 0, "SoulIdentity: user has no SBT token");

        // Обновляем метаданные через существующую систему
        try soulMetadata.getMetadata(tokenId) returns (ISoulMetadata.SoulData memory data) {
            string memory updatedAttributes = _updateLevelInJSON(data.attributes, newLevel);
            soulMetadata.updateMetadata(tokenId, updatedAttributes, data.ipfsHash);
        } catch {
            // Создаем базовые метаданные если их нет
            string memory newAttributes = string(abi.encodePacked('{"level":', _toString(newLevel), ',"reputation":100}'));
            soulMetadata.initializeMetadata(tokenId, "identity", newAttributes, "");
        }
    }

    /**
     * @dev Изменить репутацию души через SoulMetadata
     * @param user адрес пользователя
     * @param change изменение репутации (может быть отрицательным)
     */
    function updateSoulReputation(address user, int256 change) external override onlyRole(SPIRAL_ENGINE_ROLE) {
        uint256 tokenId = _getUserTokenId(user);
        require(tokenId > 0, "SoulIdentity: user has no SBT token");

        uint256 currentRep = this.getSoulReputation(user);
        uint256 newRep = change >= 0 ? currentRep + uint256(change) : 
                         (currentRep > uint256(-change) ? currentRep - uint256(-change) : 0);

        try soulMetadata.getMetadata(tokenId) returns (ISoulMetadata.SoulData memory data) {
            string memory updatedAttributes = _updateReputationInJSON(data.attributes, newRep);
            soulMetadata.updateMetadata(tokenId, updatedAttributes, data.ipfsHash);
        } catch {
            string memory newAttributes = string(abi.encodePacked('{"level":1,"reputation":', _toString(newRep), '}'));
            soulMetadata.initializeMetadata(tokenId, "identity", newAttributes, "");
        }
    }

    // === НОВАЯ DID ФУНКЦИОНАЛЬНОСТЬ ===

    /**
     * @dev Связать внешнюю идентичность с адресом
     * @param user адрес пользователя
     * @param identityType тип идентичности ("did:spiral", "did:polygon")
     * @param identityValue значение идентичности
     * @param verified статус верификации
     */
    function linkExternalIdentity(
        address user,
        string memory identityType,
        string memory identityValue,
        bool verified
    ) external override onlyRole(SPIRAL_ENGINE_ROLE) {
        require(user != address(0), "SoulIdentity: invalid user address");
        require(bytes(identityType).length > 0, "SoulIdentity: empty identity type");
        require(bytes(identityValue).length > 0, "SoulIdentity: empty identity value");
        require(_getUserTokenId(user) > 0, "SoulIdentity: user has no SBT token");

        // Проверяем, есть ли уже такой тип идентичности
        uint256 existingIndex = identityTypeToIndex[user][identityType];

        if (existingIndex > 0) {
            // Обновляем существующую идентичность
            uint256 index = existingIndex - 1;
            userIdentities[user][index].identityValue = identityValue;
            userIdentities[user][index].verified = verified;
            userIdentities[user][index].verifiedBy = verified ? msg.sender : address(0);
        } else {
            // Добавляем новую идентичность
            ExternalIdentity memory newIdentity = ExternalIdentity({
                identityType: identityType,
                identityValue: identityValue,
                verified: verified,
                createdAt: block.timestamp,
                verifiedBy: verified ? msg.sender : address(0)
            });

            userIdentities[user].push(newIdentity);
            identityTypeToIndex[user][identityType] = userIdentities[user].length;

            // Если это первая идентичность, делаем её основной
            if (userIdentities[user].length == 1) {
                primaryIdentityIndex[user] = 0;
            }
        }

        emit ExternalIdentityLinked(user, identityType, identityValue, verified, block.timestamp);
    }

    /**
     * @dev Получить основную идентичность пользователя
     * @param user адрес пользователя
     * @return identity структура основной идентичности
     */
    function getPrimaryIdentity(address user) 
        external view override returns (ExternalIdentity memory identity) {
        require(userIdentities[user].length > 0, "SoulIdentity: no identities found");
        return userIdentities[user][primaryIdentityIndex[user]];
    }

    /**
     * @dev Получить все идентичности пользователя
     * @param user адрес пользователя
     * @return identities массив всех идентичностей
     */
    function getAllIdentities(address user) 
        external view override returns (ExternalIdentity[] memory identities) {
        return userIdentities[user];
    }

    /**
     * @dev Проверить наличие идентичности определенного типа
     * @param user адрес пользователя
     * @param identityType тип идентичности
     * @return hasIdentity есть ли идентичность данного типа
     */
    function hasIdentityType(address user, string memory identityType) 
        external view override returns (bool hasIdentity) {
        return identityTypeToIndex[user][identityType] > 0;
    }

    // === ОБРАТНАЯ СОВМЕСТИМОСТЬ ===

    /**
     * @dev Связать идентичность души с DID (DEPRECATED)
     * Автоматически создает ExternalIdentity с типом "did:spiral"
     * @param did DID идентификатор
     */
    function linkSoulIdentity(string memory did) external override {
        // Для обратной совместимости - пользователь может добавить свою DID
        require(bytes(did).length > 0, "SoulIdentity: empty DID");
        require(_getUserTokenId(msg.sender) > 0, "SoulIdentity: user has no SBT token");

        // Добавляем идентичность напрямую (без роли для совместимости)
        userIdentities[msg.sender].push(ExternalIdentity({
            identityType: "did:spiral",
            identityValue: did,
            verified: false, // legacy всегда не верифицирована
            createdAt: block.timestamp,
            verifiedBy: address(0) // legacy не имеет верификатора
        }));

        // Если это первая идентичность, делаем её основной
        if (userIdentities[msg.sender].length == 1) {
            primaryIdentityIndex[msg.sender] = 0;
        }

        emit ExternalIdentityLinked(msg.sender, "did:spiral", did, false, block.timestamp);
    }

    /**
     * @dev Получить идентичность души пользователя (DEPRECATED)
     * Возвращает значение основной идентичности
     * @param user адрес пользователя
     * @return DID идентификатор основной идентичности
     */
    function getSoulIdentity(address user) external view override returns (string memory) {
        if (userIdentities[user].length == 0) return "";
        return userIdentities[user][primaryIdentityIndex[user]].identityValue;
    }

    /**
     * @dev Отвязать идентичность души (DEPRECATED)
     */
    function unlinkSoulIdentity() external override {
        // Удаляем все did:spiral идентичности пользователя
        ExternalIdentity[] storage identities = userIdentities[msg.sender];
        for (uint256 i = 0; i < identities.length; i++) {
            if (keccak256(bytes(identities[i].identityType)) == keccak256(bytes("did:spiral"))) {
                // Перемещаем последний элемент на место удаляемого
                identities[i] = identities[identities.length - 1];
                identities.pop();
                break;
            }
        }

        // Сброс индекса если удалили основную идентичность
        if (identities.length == 0) {
            primaryIdentityIndex[msg.sender] = 0;
        }
    }

    // === ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ===

    /**
     * @dev Найти первый SBT токен пользователя в существующей системе
     * @param user адрес пользователя
     * @return tokenId идентификатор токена (0 если не найден)
     */
    function _getUserTokenId(address user) private view returns (uint256) {
        uint256 balance = soulboundCore.balanceOf(user);
        if (balance == 0) return 0;

        // Поиск первого токена пользователя
        uint256 totalSupply = soulboundCore.getTotalSupply();
        for (uint256 i = 1; i <= totalSupply && i <= 1000; i++) {
            try soulboundCore.ownerOf(i) returns (address owner) {
                if (owner == user) return i;
            } catch {
                continue;
            }
        }
        return 0;
    }

    /**
     * @dev Парсинг level из JSON атрибутов (упрощенная реализация)
     * @param attributes JSON строка с атрибутами
     * @return level уровень души
     */
    function _parseLevel(string memory attributes) private pure returns (uint256) {
        // TODO: Реализовать полноценный JSON парсинг
        // Пока возвращаем дефолтное значение
        bytes memory attributesBytes = bytes(attributes);
        if (attributesBytes.length == 0) return 1;

        // Простой поиск "level":X в JSON
        // В production заменить на библиотеку JSON парсинга
        return 1; // Заглушка
    }

    /**
     * @dev Парсинг reputation из JSON атрибутов (упрощенная реализация)
     * @param attributes JSON строка с атрибутами
     * @return reputation репутация души
     */
    function _parseReputation(string memory attributes) private pure returns (uint256) {
        // TODO: Реализовать полноценный JSON парсинг
        bytes memory attributesBytes = bytes(attributes);
        if (attributesBytes.length == 0) return 100;

        // Простой поиск "reputation":X в JSON
        return 100; // Заглушка
    }

    /**
     * @dev Обновление level в JSON атрибутах (упрощенная реализация)
     * @param attributes текущие JSON атрибуты
     * @param newLevel новый уровень
     * @return updatedAttributes обновленные атрибуты
     */
    function _updateLevelInJSON(string memory attributes, uint256 newLevel) private pure returns (string memory) {
        // TODO: Реализовать полноценное обновление JSON
        return string(abi.encodePacked('{"level":', _toString(newLevel), ',"reputation":100}'));
    }

    /**
     * @dev Обновление reputation в JSON атрибутах (упрощенная реализация)
     * @param attributes текущие JSON атрибуты
     * @param newReputation новая репутация
     * @return updatedAttributes обновленные атрибуты
     */
    function _updateReputationInJSON(string memory attributes, uint256 newReputation) private pure returns (string memory) {
        // TODO: Реализовать полноценное обновление JSON
        return string(abi.encodePacked('{"level":1,"reputation":', _toString(newReputation), '}'));
    }

    /**
     * @dev Конвертация uint256 в string
     * @param value число для конвертации
     * @return строковое представление
     */
    function _toString(uint256 value) private pure returns (string memory) {
        if (value == 0) return "0";

        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }

        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }

        return string(buffer);
    }

    // === ЗАГЛУШКИ ДЛЯ ОСТАЛЬНЫХ ФУНКЦИЙ ISoulIdentity ===

    function getSoulVerificationLevel(address user) external pure override returns (uint8) {
