contracts/SoulIntegration.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @dev Интерфейс для SpiralEngine - минимальные функции для уведомлений
 */
interface ISpiralEngine {
    function notifySoulCreated(uint256 tokenId, address owner) external;
    function notifySoulRecovered(uint256 tokenId, address oldOwner, address newOwner) external;
}

/**
 * @dev Интерфейс для SoulboundCore - проверка существования токенов
 */
interface ISoulboundCore {
    function ownerOf(uint256 tokenId) external view returns (address);
    function exists(uint256 tokenId) external view returns (bool);
}

/**
 * @title SoulIntegration
 * @author Zeya888 (https://zeya888.me)
 * @dev Интеграционный контракт для уведомления SpiralEngine о событиях SBT
 * @notice Обеспечивает асинхронную обработку событий с graceful degradation
 */
contract SoulIntegration is Ownable {

    // === СОБЫТИЯ ===

    /**
     * @dev Событие при успешном уведомлении SpiralEngine
     * @param tokenId идентификатор токена
     * @param owner адрес владельца
     * @param eventType тип события ("created" или "recovered")
     */
    event SoulNotified(uint256 indexed tokenId, address indexed owner, string eventType);

    /**
     * @dev Событие при обновлении интеграции
     * @param spiralEngine новый адрес SpiralEngine
     * @param soulboundCore новый адрес SoulboundCore
     */
    event IntegrationUpdated(address indexed spiralEngine, address indexed soulboundCore);

    /**
     * @dev Событие при ошибке уведомления
     * @param tokenId идентификатор токена
     * @param eventType тип события
     * @param reason причина ошибки
     */
    event NotificationFailed(uint256 indexed tokenId, string eventType, string reason);

    // === ХРАНИЛИЩЕ ===

    // Адрес контракта SpiralEngine
    ISpiralEngine private _spiralEngine;
    // Адрес контракта SoulboundCore
    ISoulboundCore private _soulboundCore;
    // Включены ли уведомления
    bool private _notificationsEnabled = true;

    // === КОНСТРУКТОР ===

    constructor(address spiralEngine, address soulboundCore) Ownable(msg.sender) {
        require(spiralEngine != address(0), "SoulIntegration: invalid SpiralEngine address");
        require(soulboundCore != address(0), "SoulIntegration: invalid SoulboundCore address");

        _spiralEngine = ISpiralEngine(spiralEngine);
        _soulboundCore = ISoulboundCore(soulboundCore);

        emit IntegrationUpdated(spiralEngine, soulboundCore);
    }

    // === МОДИФИКАТОРЫ ===

    /**
     * @dev Проверяет, что токен существует в SoulboundCore
     */
    modifier tokenExists(uint256 tokenId) {
        require(_soulboundCore.exists(tokenId), "SoulIntegration: token does not exist");
        _;
    }

    /**
     * @dev Проверяет, что уведомления включены
     */
    modifier notificationsEnabled() {
        require(_notificationsEnabled, "SoulIntegration: notifications disabled");
        _;
    }

    // === ОСНОВНЫЕ ФУНКЦИИ ===

    /**
     * @dev Уведомление о создании нового SBT токена
     * @param tokenId идентификатор токена
     * @param owner адрес владельца токена
     */
    function notifySoulCreated(uint256 tokenId, address owner) 
        external 
        tokenExists(tokenId) 
        notificationsEnabled 
    {
        require(owner != address(0), "SoulIntegration: invalid owner address");
        require(_soulboundCore.ownerOf(tokenId) == owner, "SoulIntegration: owner mismatch");

        // Попытка уведомления с graceful degradation
        try _spiralEngine.notifySoulCreated(tokenId, owner) {
            emit SoulNotified(tokenId, owner, "created");
        } catch Error(string memory reason) {
            emit NotificationFailed(tokenId, "created", reason);
        } catch (bytes memory) {
            emit NotificationFailed(tokenId, "created", "Unknown error");
        }
    }

    /**
     * @dev Уведомление о восстановлении SBT токена
     * @param tokenId идентификатор токена
     * @param oldOwner предыдущий владелец
     * @param newOwner новый владелец
     */
    function notifySoulRecovered(uint256 tokenId, address oldOwner, address newOwner) 
        external 
        tokenExists(tokenId) 
        notificationsEnabled 
    {
        require(oldOwner != address(0), "SoulIntegration: invalid old owner address");
        require(newOwner != address(0), "SoulIntegration: invalid new owner address");
        require(oldOwner != newOwner, "SoulIntegration: owners cannot be the same");
        require(_soulboundCore.ownerOf(tokenId) == newOwner, "SoulIntegration: new owner mismatch");

        // Попытка уведомления с graceful degradation
        try _spiralEngine.notifySoulRecovered(tokenId, oldOwner, newOwner) {
            emit SoulNotified(tokenId, newOwner, "recovered");
        } catch Error(string memory reason) {
            emit NotificationFailed(tokenId, "recovered", reason);
        } catch (bytes memory) {
            emit NotificationFailed(tokenId, "recovered", "Unknown error");
        }
    }

    // === УПРАВЛЕНИЕ ИНТЕГРАЦИЕЙ ===

    /**
     * @dev Установить адрес контракта SpiralEngine (только владелец)
     * @param spiralEngine новый адрес SpiralEngine
     */
    function setSpiralEngine(address spiralEngine) external onlyOwner {
        require(spiralEngine != address(0), "SoulIntegration: invalid SpiralEngine address");
        _spiralEngine = ISpiralEngine(spiralEngine);
        emit IntegrationUpdated(spiralEngine, address(_soulboundCore));
    }

    /**
     * @dev Установить адрес контракта SoulboundCore (только владелец)
     * @param soulboundCore новый адрес SoulboundCore
     */
    function setSoulboundCore(address soulboundCore) external onlyOwner {
        require(soulboundCore != address(0), "SoulIntegration: invalid SoulboundCore address");
        _soulboundCore = ISoulboundCore(soulboundCore);
        emit IntegrationUpdated(address(_spiralEngine), soulboundCore);
    }

    /**
     * @dev Включить/выключить уведомления (только владелец)
     * @param enabled включены ли уведомления
     */
    function setNotificationsEnabled(bool enabled) external onlyOwner {
        _notificationsEnabled = enabled;
    }

    // === VIEW FUNCTIONS ===

    /**
     * @dev Получить адрес контракта SpiralEngine
     * @return адрес SpiralEngine
     */
    function getSpiralEngine() external view returns (address) {
        return address(_spiralEngine);
    }

    /**
     * @dev Получить адрес контракта SoulboundCore
     * @return адрес SoulboundCore
     */
    function getSoulboundCore() external view returns (address) {
        return address(_soulboundCore);
    }

    /**
     * @dev Проверить, включены ли уведомления
     * @return true если уведомления включены
     */
    function areNotificationsEnabled() external view returns (bool) {
        return _notificationsEnabled;
    }

    /**
     * @dev Проверить, что интеграция настроена корректно
     * @return true если все адреса установлены
     */
    function isIntegrationValid() external view returns (bool) {
        return address(_spiralEngine) != address(0) && 
               address(_soulboundCore) != address(0) && 
               _notificationsEnabled;
    }
}

contracts/SoulMetadata.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./SoulboundCore.sol";

/**
 * @title SoulMetadata
 * @author Zeya888 (https://zeya888.me)
 * @dev Газоэффективная система метаданных для SoulboundCore токенов
 * @notice Управляет метаданными SBT с оптимизацией storage layout
 */
contract SoulMetadata {

    // === СОБЫТИЯ ===

    /**
     * @dev Событие обновления метаданных
     * @param tokenId идентификатор токена
     * @param metadataType тип метаданных
     * @param version версия метаданных
     */
    event MetadataUpdated(uint256 indexed tokenId, string metadataType, uint256 version);

    /**
     * @dev Событие пакетного обновления метаданных
     * @param tokenIds массив идентификаторов токенов
     * @param count количество обновленных токенов
     */
    event MetadataBatchUpdated(uint256[] tokenIds, uint256 count);

    // === СТРУКТУРЫ ДАННЫХ ===

    /**
     * @dev Упакованная структура метаданных (оптимизирована для 2 storage slots)
     * Slot 1: metadataType (32 bytes)
     * Slot 2: version (32 bytes) 
     * Slot 3: attributes (32 bytes)
     * Slot 4: ipfsHash (32 bytes)
     */
    struct SoulData {
        string metadataType;    // "identity", "achievement", "reputation" и т.д.
        uint256 version;        // Версия метаданных для отслеживания изменений
        string attributes;      // JSON строка с атрибутами
        string ipfsHash;        // IPFS хеш для дополнительных данных
    }

    // === ХРАНИЛИЩЕ ===

    // Ссылка на основной SoulboundCore контракт
    SoulboundCore public immutable soulboundCore;

    // Mapping от tokenId к метаданным
    mapping(uint256 => SoulData) private _soulData;

    // Mapping для отслеживания инициализации метаданных
    mapping(uint256 => bool) private _metadataInitialized;

    // === МОДИФИКАТОРЫ ===

    /**
     * @dev Проверяет, что токен существует в SoulboundCore
     */
    modifier tokenExists(uint256 tokenId) {
        require(soulboundCore.exists(tokenId), "SoulMetadata: token does not exist");
        _;
    }

    /**
     * @dev Проверяет, что вызывающий является владельцем токена или владельцем контракта
     */
    modifier onlyTokenOwnerOrContractOwner(uint256 tokenId) {
        address tokenOwner = soulboundCore.ownerOf(tokenId);
        address contractOwner = soulboundCore.owner();
        require(
            msg.sender == tokenOwner || msg.sender == contractOwner,
            "SoulMetadata: not authorized"
        );
        _;
    }

    // === КОНСТРУКТОР ===

    constructor(address _soulboundCore) {
        require(_soulboundCore != address(0), "SoulMetadata: invalid address");
        soulboundCore = SoulboundCore(_soulboundCore);
    }

    // === ОСНОВНЫЕ ФУНКЦИИ ===

    /**
     * @dev Инициализация метаданных для токена
     * @param tokenId идентификатор токена
     * @param metadataType тип метаданных
     * @param attributes JSON строка с атрибутами
     * @param ipfsHash IPFS хеш (опционально)
     */
    function initializeMetadata(
        uint256 tokenId,
        string memory metadataType,
        string memory attributes,
        string memory ipfsHash
    ) external tokenExists(tokenId) onlyTokenOwnerOrContractOwner(tokenId) {
        require(!_metadataInitialized[tokenId], "SoulMetadata: already initialized");

        _soulData[tokenId] = SoulData({
            metadataType: metadataType,
            version: 1,
            attributes: attributes,
            ipfsHash: ipfsHash
        });

        _metadataInitialized[tokenId] = true;

        emit MetadataUpdated(tokenId, metadataType, 1);
    }

    /**
     * @dev Обновление метаданных токена
     * @param tokenId идентификатор токена
     * @param attributes новые атрибуты
     * @param ipfsHash новый IPFS хеш (опционально)
     */
    function updateMetadata(
        uint256 tokenId,
        string memory attributes,
        string memory ipfsHash
    ) external tokenExists(tokenId) onlyTokenOwnerOrContractOwner(tokenId) {
        require(_metadataInitialized[tokenId], "SoulMetadata: not initialized");

        SoulData storage data = _soulData[tokenId];
        data.attributes = attributes;
        data.ipfsHash = ipfsHash;
        data.version += 1;

        emit MetadataUpdated(tokenId, data.metadataType, data.version);
    }

    /**
     * @dev Пакетное обновление метаданных
     * @param tokenIds массив идентификаторов токенов
     * @param attributesArray массив атрибутов
     * @param ipfsHashes массив IPFS хешей
     */
    function batchUpdateMetadata(
        uint256[] memory tokenIds,
        string[] memory attributesArray,
        string[] memory ipfsHashes
    ) external {
        require(
            tokenIds.length == attributesArray.length && 
            tokenIds.length == ipfsHashes.length,
            "SoulMetadata: arrays length mismatch"
        );
        require(tokenIds.length <= 50, "SoulMetadata: batch too large");

        for (uint256 i = 0; i < tokenIds.length; i++) {
            uint256 tokenId = tokenIds[i];

            require(soulboundCore.exists(tokenId), "SoulMetadata: token does not exist");
            require(_metadataInitialized[tokenId], "SoulMetadata: not initialized");

            address tokenOwner = soulboundCore.ownerOf(tokenId);
            address contractOwner = soulboundCore.owner();
            require(
                msg.sender == tokenOwner || msg.sender == contractOwner,
                "SoulMetadata: not authorized"
            );

            SoulData storage data = _soulData[tokenId];
            data.attributes = attributesArray[i];
            data.ipfsHash = ipfsHashes[i];
            data.version += 1;
        }

        emit MetadataBatchUpdated(tokenIds, tokenIds.length);
    }

    // === VIEW FUNCTIONS ===

    /**
     * @dev Получить метаданные токена
     * @param tokenId идентификатор токена
     * @return SoulData структура с метаданными
     */
    function getMetadata(uint256 tokenId) external view tokenExists(tokenId) returns (SoulData memory) {
        require(_metadataInitialized[tokenId], "SoulMetadata: not initialized");
        return _soulData[tokenId];
    }

    /**
     * @dev Проверить, инициализированы ли метаданные
     * @param tokenId идентификатор токена
     * @return true если метаданные инициализированы
     */
    function isInitialized(uint256 tokenId) external view returns (bool) {
        return _metadataInitialized[tokenId];
    }

    /**
     * @dev Получить JSON URI для токена (совместимость с OpenSea)
     * @param tokenId идентификатор токена
     * @return JSON строка с метаданными
     */
    function getTokenURI(uint256 tokenId) external view tokenExists(tokenId) returns (string memory) {
        if (!_metadataInitialized[tokenId]) {
            // Возвращаем пустую строку для fallback к базовым метаданным SoulboundCore
            return "";
        }

        SoulData memory data = _soulData[tokenId];

        // Формируем JSON метаданные
        return string(abi.encodePacked(
            '{"name": "Soul #', _toString(tokenId), 
            '", "description": "Soulbound Token from Amanita Ecosystem",',
            '"type": "', data.metadataType, '",',
            '"version": ', _toString(data.version), ',',
            '"attributes": ', data.attributes,
            bytes(data.ipfsHash).length > 0 ? string(abi.encodePacked(',"ipfs": "', data.ipfsHash, '"')) : '',
            '}'
        ));
    }

    /**
     * @dev Получить версию метаданных
     * @param tokenId идентификатор токена
     * @return версия метаданных
     */
    function getMetadataVersion(uint256 tokenId) external view tokenExists(tokenId) returns (uint256) {
        require(_metadataInitialized[tokenId], "SoulMetadata: not initialized");
        return _soulData[tokenId].version;
    }

    // === ВНУТРЕННИЕ ФУНКЦИИ ===

    /**
     * @dev Преобразование uint256 в string
     * @param value число для преобразования
     * @return строковое представление числа
     */
    function _toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) {
            return "0";
        }
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }
}

contracts/SoulRecovery.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./SoulboundCore.sol";

/**
 * @title SoulRecovery
 * @author Zeya888 (https://zeya888.me)
 * @dev Система восстановления доступа к SoulboundCore токенам через guardian'ов
 * @notice Упрощенная система с одним guardian на пользователя
 */
contract SoulRecovery {

    // === СОБЫТИЯ ===

    /**
     * @dev Событие установки guardian'а
     * @param tokenId идентификатор токена
     * @param owner владелец токена
     * @param guardian адрес guardian'а
     */
    event GuardianSet(uint256 indexed tokenId, address indexed owner, address indexed guardian);

    /**
     * @dev Событие инициации восстановления
     * @param tokenId идентификатор токена
     * @param oldOwner старый владелец
     * @param newOwner новый владелец
     * @param guardian guardian, инициировавший восстановление
     */
    event RecoveryInitiated(uint256 indexed tokenId, address indexed oldOwner, address indexed newOwner, address guardian);

    /**
     * @dev Событие завершения восстановления
     * @param tokenId идентификатор токена
     * @param newOwner новый владелец
     */
    event RecoveryCompleted(uint256 indexed tokenId, address indexed newOwner);

    /**
     * @dev Событие отмены восстановления
     * @param tokenId идентификатор токена
     * @param owner владелец токена
     */
    event RecoveryCancelled(uint256 indexed tokenId, address indexed owner);

    // === СТРУКТУРЫ ДАННЫХ ===

    /**
     * @dev Информация о guardian'е для токена
     */
    struct GuardianInfo {
        address guardian;           // Адрес guardian'а
        uint256 setTimestamp;      // Время установки guardian'а
        bool isActive;             // Активен ли guardian
    }

    /**
     * @dev Информация о процессе восстановления
     */
    struct RecoveryInfo {
        address newOwner;          // Новый владелец
        address guardian;          // Guardian, инициировавший восстановление
        uint256 initiatedAt;       // Время инициации
        bool isActive;             // Активен ли процесс восстановления
    }

    // === ХРАНИЛИЩЕ ===

    // Ссылка на основной SoulboundCore контракт
    SoulboundCore public immutable soulboundCore;

    // Mapping от tokenId к информации о guardian'е
    mapping(uint256 => GuardianInfo) private _guardians;

    // Mapping от tokenId к информации о восстановлении
    mapping(uint256 => RecoveryInfo) private _recoveries;

    // Время задержки для восстановления (24 часа)
    uint256 public constant RECOVERY_DELAY = 24 hours;

    // Минимальное время после установки guardian'а перед возможностью восстановления (7 дней)
    uint256 public constant GUARDIAN_DELAY = 7 days;

    // === МОДИФИКАТОРЫ ===

    /**
     * @dev Проверяет, что токен существует в SoulboundCore
     */
    modifier tokenExists(uint256 tokenId) {
        require(soulboundCore.exists(tokenId), "SoulRecovery: token does not exist");
        _;
    }

    /**
     * @dev Проверяет, что вызывающий является владельцем токена
     */
    modifier onlyTokenOwner(uint256 tokenId) {
        require(
            soulboundCore.ownerOf(tokenId) == msg.sender,
            "SoulRecovery: not token owner"
        );
        _;
    }

    /**
     * @dev Проверяет, что вызывающий является guardian'ом токена
     */
    modifier onlyGuardian(uint256 tokenId) {
        require(
            _guardians[tokenId].guardian == msg.sender && _guardians[tokenId].isActive,
            "SoulRecovery: not authorized guardian"
        );
        _;
    }

    // === КОНСТРУКТОР ===

    constructor(address _soulboundCore) {
        require(_soulboundCore != address(0), "SoulRecovery: invalid address");
        soulboundCore = SoulboundCore(_soulboundCore);
    }

    // === ОСНОВНЫЕ ФУНКЦИИ ===

    /**
     * @dev Установка guardian'а для токена
     * @param tokenId идентификатор токена
     * @param guardian адрес guardian'а
     */
    function setGuardian(uint256 tokenId, address guardian) 
        external 
        tokenExists(tokenId) 
        onlyTokenOwner(tokenId) 
    {
        require(guardian != address(0), "SoulRecovery: invalid guardian address");
        require(guardian != msg.sender, "SoulRecovery: cannot be self guardian");
        require(guardian != soulboundCore.ownerOf(tokenId), "SoulRecovery: guardian cannot be owner");

        _guardians[tokenId] = GuardianInfo({
            guardian: guardian,
            setTimestamp: block.timestamp,
            isActive: true
        });

        emit GuardianSet(tokenId, msg.sender, guardian);
    }

    /**
     * @dev Удаление guardian'а
     * @param tokenId идентификатор токена
     */
    function removeGuardian(uint256 tokenId) 
        external 
        tokenExists(tokenId) 
        onlyTokenOwner(tokenId) 
    {
        require(_guardians[tokenId].isActive, "SoulRecovery: no active guardian");

        delete _guardians[tokenId];

        emit GuardianSet(tokenId, msg.sender, address(0));
    }

    /**
     * @dev Инициация процесса восстановления
     * @param tokenId идентификатор токена
     * @param newOwner новый владелец токена
     */
    function initiateRecovery(uint256 tokenId, address newOwner) 
        external 
        tokenExists(tokenId) 
        onlyGuardian(tokenId) 
    {
        require(newOwner != address(0), "SoulRecovery: invalid new owner");
        require(newOwner != soulboundCore.ownerOf(tokenId), "SoulRecovery: same owner");
        require(!_recoveries[tokenId].isActive, "SoulRecovery: recovery already active");

        // Проверяем, что guardian был установлен достаточно давно
        require(
            block.timestamp >= _guardians[tokenId].setTimestamp + GUARDIAN_DELAY,
            "SoulRecovery: guardian delay not passed"
        );

        _recoveries[tokenId] = RecoveryInfo({
            newOwner: newOwner,
            guardian: msg.sender,
            initiatedAt: block.timestamp,
            isActive: true
        });

        emit RecoveryInitiated(tokenId, soulboundCore.ownerOf(tokenId), newOwner, msg.sender);
    }

    /**
     * @dev Подтверждение восстановления (после задержки)
     * @param tokenId идентификатор токена
     */
    function confirmRecovery(uint256 tokenId) 
        external 
        tokenExists(tokenId) 
        onlyGuardian(tokenId) 
    {
        RecoveryInfo storage recovery = _recoveries[tokenId];
        require(recovery.isActive, "SoulRecovery: no active recovery");
        require(recovery.guardian == msg.sender, "SoulRecovery: not recovery guardian");
        require(
            block.timestamp >= recovery.initiatedAt + RECOVERY_DELAY,
            "SoulRecovery: recovery delay not passed"
        );

        // Сохраняем данные для восстановления
        address newOwner = recovery.newOwner;

        // Выполняем фактическое восстановление через SoulboundCore
        soulboundCore.executeRecovery(tokenId, newOwner);

        // Очищаем процесс восстановления ПОСЛЕ успешного восстановления
        delete _recoveries[tokenId];

        emit RecoveryCompleted(tokenId, newOwner);
    }

    /**
     * @dev Отмена процесса восстановления (владельцем токена)
     * @param tokenId идентификатор токена
     */
    function cancelRecovery(uint256 tokenId) 
        external 
        tokenExists(tokenId) 
        onlyTokenOwner(tokenId) 
    {
        require(_recoveries[tokenId].isActive, "SoulRecovery: no active recovery");

        delete _recoveries[tokenId];

        emit RecoveryCancelled(tokenId, msg.sender);
    }

    // === VIEW FUNCTIONS ===

    /**
     * @dev Получить информацию о guardian'е
     * @param tokenId идентификатор токена
     * @return GuardianInfo структура с информацией о guardian'е
     */
    function getGuardianInfo(uint256 tokenId) external view tokenExists(tokenId) returns (GuardianInfo memory) {
        return _guardians[tokenId];
    }

    /**
     * @dev Получить адрес guardian'а
     * @param tokenId идентификатор токена
     * @return адрес guardian'а или address(0) если не установлен
     */
    function getGuardian(uint256 tokenId) external view returns (address) {
        return _guardians[tokenId].isActive ? _guardians[tokenId].guardian : address(0);
    }

    /**
     * @dev Проверить, есть ли активный guardian
     * @param tokenId идентификатор токена
     * @return true если есть активный guardian
     */
    function hasActiveGuardian(uint256 tokenId) external view returns (bool) {
        return _guardians[tokenId].isActive;
    }

    /**
     * @dev Получить информацию о процессе восстановления
     * @param tokenId идентификатор токена
     * @return RecoveryInfo структура с информацией о восстановлении
     */
    function getRecoveryInfo(uint256 tokenId) external view tokenExists(tokenId) returns (RecoveryInfo memory) {
        return _recoveries[tokenId];
    }

    /**
     * @dev Проверить, активен ли процесс восстановления
     * @param tokenId идентификатор токена
     * @return true если процесс восстановления активен
     */
    function isRecoveryActive(uint256 tokenId) external view returns (bool) {
        return _recoveries[tokenId].isActive;
    }

    /**
     * @dev Проверить, можно ли подтвердить восстановление
     * @param tokenId идентификатор токена
     * @return true если восстановление можно подтвердить
     */
    function canConfirmRecovery(uint256 tokenId) external view returns (bool) {
        RecoveryInfo memory recovery = _recoveries[tokenId];
        return recovery.isActive && 
               block.timestamp >= recovery.initiatedAt + RECOVERY_DELAY;
    }

    /**
     * @dev Получить время до возможности подтверждения восстановления
     * @param tokenId идентификатор токена
     * @return секунды до возможности подтверждения (0 если уже можно)
     */
    function getRecoveryTimeLeft(uint256 tokenId) external view returns (uint256) {
        RecoveryInfo memory recovery = _recoveries[tokenId];
        if (!recovery.isActive) {
            return 0;
        }

        uint256 confirmTime = recovery.initiatedAt + RECOVERY_DELAY;
        if (block.timestamp >= confirmTime) {
            return 0;
        }

        return confirmTime - block.timestamp;
    }
}

contracts/SpiralEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "./interfaces/ISoulIdentity.sol";
import "./IERC5192.sol";

/**
 * @title SpiralEngine
 * @author Zeya888 (https://zeya888.me)
 * @dev Основной контракт спиральной иерархии через 12-гранные круги
 * @notice Управляет инвайтами, активацией пользователей и назначением ролей в спиральной системе
 * @notice SBT функциональность делегируется в SoulIdentity контракт
 */
contract SpiralEngine is ERC721, AccessControl, IERC5192 {
    uint256 private _tokenIdCounter;

    // Роль продавца для доступа к минтингу инвайтов
    bytes32 public constant SELLER_ROLE = keccak256("SELLER_ROLE");

    // Роль активатора для активации пользователей и назначения ролей
    bytes32 public constant ACTIVATOR_ROLE = keccak256("ACTIVATOR_ROLE");

    // === ОСНОВНЫЕ ДАННЫЕ ИНВАЙТОВ ===

    // Маппинг: inviteCode (уникальный строковый код) => tokenId (NFT инвайта)
    mapping(string => uint256) public inviteCodeToTokenId;

    // Маппинг: inviteCode => существует ли код (для корректной проверки дублирования)
    mapping(string => bool) public inviteCodeExists;

    // Маппинг: tokenId (NFT инвайта) => inviteCode (уникальный строковый код)
    mapping(uint256 => string) public tokenIdToInviteCode;

    // Маппинг: tokenId => использован ли инвайт
    mapping(uint256 => bool) public isInviteUsed;

    // Маппинг: user (адрес) => использованный инвайт (tokenId)
    mapping(address => uint256) public usedInviteByUser;

    // Маппинг: tokenId => срок действия инвайта (timestamp, 0 если бессрочный)
    mapping(uint256 => uint256) public inviteExpiry;

    // Маппинг: tokenId => дата создания инвайта (timestamp)
    mapping(uint256 => uint256) public inviteCreatedAt;

    // Маппинг: tokenId => адрес создателя (minter)
    mapping(uint256 => address) public inviteMinter;

    // Маппинг: tokenId => адрес первого владельца инвайта
    mapping(uint256 => address) public inviteFirstOwner;

    // Маппинг: user (адрес) => список всех его инвайтов (tokenId)
    mapping(address => uint256[]) private userInvites;

    // Счётчик общего количества использованных инвайтов
    uint256 public totalInvitesUsed;

    // Счётчик общего количества выданных инвайтов
    uint256 public totalInvitesMinted;

    // Маппинг: tokenId => история всех владельцев (адреса)
    mapping(uint256 => address[]) public inviteTransferHistory;

    // Массив всех активированных пользователей
    address[] public activatedUsers;

    // Маппинг: user (адрес) => количество заминченных инвайтов для этого пользователя
    mapping(address => uint256) public userInviteCount;

    // === ОТСЛЕЖИВАНИЕ ОТВЕТСТВЕННОСТИ ===

    // Маппинг: кто активировал пользователя
    mapping(address => address) public userActivator;

    // Маппинг: кто назначил роль SELLER_ROLE
    mapping(address => address) public sellerNominator;

    // Маппинг: кого активировал данный активатор
    mapping(address => address[]) public activatedBy;

    // Маппинг: кого назначил селлером данный номинатор
    mapping(address => address[]) public nominatedSellers;

    // === СИСТЕМА САНКЦИЙ ===

    // Маппинг: счетчик нарушений для каждого пользователя
    mapping(address => uint256) public violationCount;

    // Маппинг: до какого времени заблокирован пользователь
    mapping(address => uint256) public suspensionUntil;

    // Маппинг: нарушения активированных пользователей (для активатора)
    mapping(address => uint256) public activationViolations;

    // Маппинг: нарушения назначенных селлеров (для номинатора)
    mapping(address => uint256) public nominationViolations;

    // === ССЫЛКА НА SOUL IDENTITY ===

    // Адрес контракта SoulIdentity для делегирования SBT функций
    ISoulIdentity public soulIdentity;

    // === СТРУКТУРЫ ДЛЯ ДИАГНОСТИКИ ===

    /**
     * @dev Структура для хранения информации об инвайте
     */
    struct InviteInfo {
        string inviteCode;           // Код инвайта
        uint256 tokenId;            // ID токена инвайта
        bool isUsed;                // Статус использования
        address activatedBy;        // Адрес активатора (если инвайт использован)
        uint256 activationTime;     // Время активации
        uint256 expiry;             // Срок действия
    }

    /**
     * @dev Структура для полной диагностики состояния селлера
     */
    struct SellerDiagnostics {
        bool isActivated;           // Статус активации пользователя
        uint256 usedInviteTokenId;  // ID использованного инвайта
        bool hasSellerRole;         // Наличие роли SELLER_ROLE
        bool hasActivatorRole;      // Наличие роли ACTIVATOR_ROLE
        InviteInfo[] userInvites;   // Массив инвайтов пользователя
        uint256 totalInvitesMinted; // Общее количество заминченных инвайтов
    }

    // === СОБЫТИЯ ===

    event InviteMinted(address indexed minter, uint256 indexed tokenId, string inviteCode, uint256 expiry);
    event InviteUsed(address indexed user, uint256 indexed tokenId, string inviteCode);
    event UserActivated(address indexed user, address indexed activator, uint256 timestamp);
    event SellerRoleGranted(address indexed user, address indexed nominator, uint256 timestamp);
    event UserSuspended(address indexed user, uint256 until, string reason);
    event SoulIdentityUpdated(address indexed oldSoulIdentity, address indexed newSoulIdentity);

    // === КОНСТРУКТОР ===

    constructor() ERC721("SpiralInvite", "SPIRAL") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(SELLER_ROLE, msg.sender);
        _grantRole(ACTIVATOR_ROLE, msg.sender);
    }

    // === ОСНОВНЫЕ ФУНКЦИИ ИНВАЙТОВ ===

    /**
     * @dev Минт нового инвайта
     * @param inviteCode уникальный код инвайта
     * @param expiry срок действия (0 = бессрочный)
     * @return tokenId идентификатор созданного NFT
     */
    function mintInvite(string memory inviteCode, uint256 expiry) public onlyRole(SELLER_ROLE) returns (uint256) {
        require(bytes(inviteCode).length > 0, "SpiralEngine: empty invite code");
        require(!inviteCodeExists[inviteCode], "SpiralEngine: invite code already exists");

        uint256 tokenId = _tokenIdCounter++;
        _mint(msg.sender, tokenId);

        inviteCodeToTokenId[inviteCode] = tokenId;
        inviteCodeExists[inviteCode] = true;
        tokenIdToInviteCode[tokenId] = inviteCode;
        inviteExpiry[tokenId] = expiry;
        inviteCreatedAt[tokenId] = block.timestamp;
        inviteMinter[tokenId] = msg.sender;
        inviteFirstOwner[tokenId] = msg.sender;

        userInvites[msg.sender].push(tokenId);
        userInviteCount[msg.sender]++;
        totalInvitesMinted++;

        emit InviteMinted(msg.sender, tokenId, inviteCode, expiry);
        return tokenId;
    }

    /**
     * @dev Активация пользователя с помощью инвайта
     * @param inviteCode код инвайта
     * @param user адрес пользователя для активации
     * @param newInviteCodes новые инвайты для пользователя
     * @param expiry срок действия новых инвайтов
     */
    function activateUser(
        string memory inviteCode, 
        address user, 
        string[] memory newInviteCodes, 
        uint256 expiry
    ) public onlyRole(ACTIVATOR_ROLE) {
        require(user != address(0), "SpiralEngine: invalid user address");
        require(usedInviteByUser[user] == 0, "SpiralEngine: user already activated");
        require(newInviteCodes.length == 12, "SpiralEngine: must provide exactly 12 invite codes");
        require(activatedBy[msg.sender].length < 12, "SpiralEngine: activator circle limit reached");

        uint256 tokenId = _validateInviteCode(inviteCode, msg.sender);
        require(!isInviteUsed[tokenId], "SpiralEngine: invite already used");
        require(inviteExpiry[tokenId] == 0 || inviteExpiry[tokenId] > block.timestamp, "SpiralEngine: invite expired");

        // Используем инвайт
        isInviteUsed[tokenId] = true;
        usedInviteByUser[user] = tokenId + 1; // +1 чтобы избежать конфликта с tokenId = 0
        totalInvitesUsed++;

        // Записываем активатора
        userActivator[user] = msg.sender;
        activatedBy[msg.sender].push(user);
        activatedUsers.push(user);

        // Создаем новые инвайты для пользователя
        for (uint256 i = 0; i < newInviteCodes.length; i++) {
            require(bytes(newInviteCodes[i]).length > 0, "SpiralEngine: empty invite code");
            require(!inviteCodeExists[newInviteCodes[i]], "SpiralEngine: invite code already exists");

            uint256 newTokenId = _tokenIdCounter++;
            _mint(user, newTokenId);

            inviteCodeToTokenId[newInviteCodes[i]] = newTokenId;
            inviteCodeExists[newInviteCodes[i]] = true;
            tokenIdToInviteCode[newTokenId] = newInviteCodes[i];
            inviteExpiry[newTokenId] = expiry;
            inviteCreatedAt[newTokenId] = block.timestamp;
            inviteMinter[newTokenId] = user;
            inviteFirstOwner[newTokenId] = user;

            userInvites[user].push(newTokenId);
            userInviteCount[user]++;
            totalInvitesMinted++;

            emit InviteMinted(user, newTokenId, newInviteCodes[i], expiry);
        }

        emit UserActivated(user, msg.sender, block.timestamp);
    }

    /**
     * @dev Назначение роли продавца
     * @param user адрес пользователя
     */
    function grantSellerRole(address user) public onlyRole(ACTIVATOR_ROLE) {
        require(user != address(0), "SpiralEngine: invalid user address");
        require(usedInviteByUser[user] > 0, "SpiralEngine: user not activated");
        require(!hasRole(SELLER_ROLE, user), "SpiralEngine: user already has seller role");

        _grantRole(SELLER_ROLE, user);
        sellerNominator[user] = msg.sender;
        nominatedSellers[msg.sender].push(user);

        emit SellerRoleGranted(user, msg.sender, block.timestamp);
    }

    /**
     * @dev Приостановка пользователя
     * @param user адрес пользователя
     * @param duration продолжительность приостановки в секундах
     * @param reason причина приостановки
     */
    function suspendUser(address user, uint256 duration, string memory reason) public onlyRole(DEFAULT_ADMIN_ROLE) {
        require(user != address(0), "SpiralEngine: invalid user address");
        require(usedInviteByUser[user] > 0, "SpiralEngine: user not activated");
        require(duration > 0, "SpiralEngine: invalid duration");

        suspensionUntil[user] = block.timestamp + duration;
        violationCount[user]++;

        // Каскадные санкции
        if (userActivator[user] != address(0)) {
            activationViolations[userActivator[user]]++;
        }
        if (sellerNominator[user] != address(0)) {
            nominationViolations[sellerNominator[user]]++;
        }

        emit UserSuspended(user, suspensionUntil[user], reason);
    }

    // === ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ===

    /**
     * @dev Валидация инвайт кода
     * @param inviteCode код инвайта
     * @param activator адрес активатора
     * @return tokenId идентификатор токена
     */
    function _validateInviteCode(string memory inviteCode, address activator) internal view returns (uint256) {
        require(inviteCodeExists[inviteCode], "SpiralEngine: invite code not found");
        uint256 tokenId = inviteCodeToTokenId[inviteCode];
        require(inviteMinter[tokenId] == activator, "SpiralEngine: invite not from activator");
        return tokenId;
    }

    /**
     * @dev Получить размер круга активатора
     * @param activator адрес активатора
     * @return размер круга
     */
    function getCircleSize(address activator) public view returns (uint256) {
        return activatedBy[activator].length;
    }

    /**
     * @dev Получить членов круга активатора
     * @param activator адрес активатора
